using System.Numerics;
using SmSim;

namespace SmNet.Tests;

/// <summary>
/// Phase B T2b review fix (protocol 94): a Classic snapshot of at most 16 records and a Classic scoreboard write the same bytes as protocol 91 did. The expected hex was written once
/// by protocol 91's own serializer (origin/main d4db1299, <c>Protocol.Write</c>) from exactly the synthetic data below (no original bytes) and is pinned here as a literal: a later change to the Classic
/// wire, however small, fails this test.
/// </summary>
public class Protocol91GoldenTests
{
    const string Snapshot91 = "";
    const string Scoreboard91 = "";

    static PlayerState Body(int id, int k) => new(id, new Vector3(3.25f * k - 20f, 1.5f * k, 0.5f + 0.125f * k), new Vector3(0.5f * k, -1.25f, 0.25f), 0.3f * k - 2f, k % 3 != 0)
    {
        Alive = k % 5 != 4, Class = k % 4, Team = k % 2 == 0 ? Team.SpaceMarines : Team.Chaos, Slot = (WeaponSlot)(k % 3), Primary = k % 6, Pistol = 1, Second = 2, MeleeChoice = 0,
        Pitch = -0.4f + 0.05f * k, Aiming = k % 2 == 1, Charging = k == 3, Throwing = k == 7, EvadeTicks = k % 4, EvadeDirection = (EvadeDirection)(k % 3), DamageCount = (byte)(k % 8), DamageShield = k % 2 == 0,
        DamageHealth = k % 3 == 1, Health = 80f + k, Shield = 40f - k, Cooldown = 0.25f, ReloadLeft = 0.5f, SinceDamage = 1.5f, Grenades = 2, Heat = 0.5f, MeleeTime = 0.125f,
    };

    /// <summary>16 records (the recipient's full), every other block full (12 projectiles, 4 kills, 3 control points, the hit block, 6 shots of every kind).</summary>
    internal static Snapshot ClassicSnapshot()
    {
        var players = Enumerable.Range(0, 16).Select(k => Body(k + 1, k)).ToArray();
        return new Snapshot(123456, 123450, 3, players, Self: 5,
            Projectiles: [.. Enumerable.Range(0, 12).Select(k => new ProjectileView(60000 + k, 3, 1, new Vector3(k, -k, 2f), k % 2 == 0 ? ProjectileFlags.None : ProjectileFlags.Detonated))],
            Match: new MatchView(MatchState.Playing, Team.None, 5400, 12, 9, GameMode.SeizeGround),
            Kills: [.. Enumerable.Range(0, 4).Select(k => new KillView(100 + k, k + 1, k + 2, KillCause.Weapon, 2, Vector3.UnitX, k == 1))],
            Points: [new ControlPointView(Team.SpaceMarines, Team.SpaceMarines, 1f, false), new ControlPointView(Team.Chaos, Team.SpaceMarines, 0.5f, true), new ControlPointView(Team.None, Team.None, 0f, false)],
            Hits: new HitView(3, 12, 34, 1, 7, HitFlags.All, 55f, 10f),
            Shots: [.. Enumerable.Range(0, 6).Select(k => new ShotView(players[k * 2 + 1].PlayerId, 4, k % 3, (ShotHit)(k % 4), (ShotHit)(k % 4) == ShotHit.World ? 9 : -1, players[k * 2 + 1].Position + new Vector3(10f, -5f, 1f), k % 4, (ShotHit)(k % 4) is ShotHit.Body && k % 2 == 1))],
            InputSlack: 17);
    }

    /// <summary>16 rows with names, pings, headshots and assists, and two spectators.</summary>
    internal static Scoreboard ClassicBoard() => new(98765, true, 41, 900f, false,
        [.. Enumerable.Range(1, 16).Select(i => new ScoreEntry(i, i % 2 == 0 ? Team.SpaceMarines : Team.Chaos, i % 4, i, 16 - i, (ushort)(i * 3), i % 3 - 1, "Player" + i, 20 + i, i == 4, i % 5, i % 2))],
        Spectators: [new SpectatorEntry(200, "Watcher"), new SpectatorEntry(201)]);

    [Fact]
    public void A_classic_snapshot_of_16_records_writes_protocol_91s_bytes()
    {
        var bytes = Protocol.Write(ClassicSnapshot());
        Assert.Equal(Snapshot91, Convert.ToHexString(bytes));
        Assert.Equal(16, bytes[13 + 1 + 12 * 14]);   // the count byte: 16 records, no lean block (bit 7 clear)
        var back = Assert.IsType<Snapshot>(Protocol.Read(bytes));
        Assert.Equal(0, back.Lean);
    }

    [Fact]
    public void A_classic_scoreboard_writes_protocol_91s_bytes() =>
        Assert.Equal(Scoreboard91, Convert.ToHexString(Protocol.Write(ClassicBoard())));
}
